import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.UpdatePlayerGameType{GameType: 2, PlayerUniqueID: 7, Tick: 200}
ADVENTURE = bytes.fromhex("040ec801")

# generated by gophertunnel b8bd735:
# &packet.UpdatePlayerGameType{GameType: -1, PlayerUniqueID: -5, Tick: 0}
NEGATIVE = bytes.fromhex("010900")

# generated by gophertunnel b8bd735:
# &packet.UpdatePlayerGameType{GameType: 6, PlayerUniqueID: -9007199254740993, Tick: 4294967296}
WIDE = bytes.fromhex("0c81808080808080208080808010")

GOLDENS = [
    pytest.param(
        v2225.UpdatePlayerGameTypePacket(player_game_type=v2225.GameType.ADVENTURE, target_player=7, tick=200),
        ADVENTURE,
        id="adventure",
    ),
    pytest.param(
        v2225.UpdatePlayerGameTypePacket(player_game_type=v2225.GameType.UNDEFINED, target_player=-5, tick=0),
        NEGATIVE,
        id="negative",
    ),
    pytest.param(
        v2225.UpdatePlayerGameTypePacket(
            player_game_type=v2225.GameType.SPECTATOR, target_player=-9007199254740993, tick=4294967296
        ),
        WIDE,
        id="wide",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_update_player_game_type_is_packet_151(version):
    assert version.PACKETS[151] is version.UpdatePlayerGameTypePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_player_game_type_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_player_game_type_decodes_from_its_golden(packet, golden):
    assert v2225.UpdatePlayerGameTypePacket.from_bytes(golden) == packet


def test_update_player_game_type_rejects_an_empty_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.UpdatePlayerGameTypePacket.from_bytes(b"")
